	"oras.land/oras-go/v2/registry/remote/auth"
)

const (
	SchemeHTTP  = "http"
	SchemeHTTPS = "https"
	SchemeFlipt = "flipt"
)

// Store is a type which can retrieve Flipt feature files from a target repository and reference
// Repositories can be local (OCI layout directories on the filesystem) or a remote registry
type Store struct {
	opts   StoreOptions
	logger *zap.Logger
	local  oras.Target
}

// StoreOptions are used to configure call to NewStore
// This shouldn't be handled directory, instead use one of the function options
// e.g. WithBundleDir or WithCredentials
type StoreOptions struct {
	bundleDir string
	auth      *struct {
		username string
		password string
	}
}

// WithCredentials configures username and password credentials used for authenticating
// with remote registries
func WithCredentials(user, pass string) containers.Option[StoreOptions] {
	return func(so *StoreOptions) {
		so.auth = &struct {
			username string
			password string
		}{
			username: user,
			password: pass,
		}
	}
}

// NewStore constructs and configures an instance of *Store for the provided config
func NewStore(logger *zap.Logger, dir string, opts ...containers.Option[StoreOptions]) (*Store, error) {
	store := &Store{
		opts: StoreOptions{
			bundleDir: dir,
		},
		logger: logger,
		local:  memory.New(),
	}

	containers.ApplyAll(&store.opts, opts...)

	return store, nil
}

type Reference struct {
	registry.Reference
	Scheme string
}

func ParseReference(repository string) (Reference, error) {
	scheme, repository, match := strings.Cut(repository, "://")
	// support empty scheme as remote and https
	if !match {
		repository = scheme
		scheme = SchemeHTTPS
	}

	if !strings.Contains(repository, "/") {
		repository = "local/" + repository
		scheme = SchemeFlipt
	}

	ref, err := registry.ParseReference(repository)
	if err != nil {
		return Reference{}, err
	}

	switch scheme {
	case SchemeHTTP, SchemeHTTPS:
	case SchemeFlipt:
		if ref.Registry != "local" {
			return Reference{}, fmt.Errorf("unexpected local reference: %q", ref)
		}
	default:
		return Reference{}, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", scheme)
	}

	return Reference{
		Reference: ref,
		Scheme:    scheme,
	}, nil
}

func (s *Store) getTarget(ref Reference) (oras.Target, error) {
	switch ref.Scheme {
	case SchemeHTTP, SchemeHTTPS:
		remote, err := remote.NewRepository(fmt.Sprintf("%s/%s", ref.Registry, ref.Repository))
		if err != nil {
			return nil, err
		}

		remote.PlainHTTP = ref.Scheme == "http"

		if s.opts.auth != nil {
			remote.Client = &auth.Client{
				Credential: auth.StaticCredential(ref.Registry, auth.Credential{
					Username: s.opts.auth.username,
					Password: s.opts.auth.password,
				}),
			}
		}

		return remote, nil
	case SchemeFlipt:
		// build the store once to ensure it is valid
		store, err := oci.New(path.Join(s.opts.bundleDir, ref.Repository))
		if err != nil {
			return nil, err
		}

		store.AutoSaveIndex = true

		return store, nil
	}

	return nil, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", ref.Scheme)
}

// FetchOptions configures a call to Fetch
type FetchOptions struct {
	IfNoMatch digest.Digest
}

// FetchResponse contains any fetched files for the given tracked reference
// If Matched == true, then the supplied IfNoMatch digest matched and Files should be nil
type FetchResponse struct {
	Digest  digest.Digest
	Files   []fs.File
	Matched bool
}

// IfNoMatch configures the call to Fetch to return early if the supplied
// digest matches the target manifest pointed at by the underlying reference
// This is a cache optimization to skip re-fetching resources if the contents
// has already been seen by the caller
func IfNoMatch(digest digest.Digest) containers.Option[FetchOptions] {
	return func(fo *FetchOptions) {
		fo.IfNoMatch = digest
	}
}

// Fetch retrieves the associated files for the tracked repository and reference
// It can optionally be configured to skip fetching given the caller has a digest
// that matches the current reference target
func (s *Store) Fetch(ctx context.Context, ref Reference, opts ...containers.Option[FetchOptions]) (*FetchResponse, error) {
	var options FetchOptions
	containers.ApplyAll(&options, opts...)

	store, err := s.getTarget(ref)
	if err != nil {
		return nil, err
	}

	desc, err := oras.Copy(ctx,
		store,
		ref.Reference.Reference,
		s.local,
		ref.Reference.Reference,
		oras.DefaultCopyOptions)
	if err != nil {
		return nil, err
	}

	bytes, err := content.FetchAll(ctx, s.local, desc)
	if err != nil {
		return nil, err
	}

	var manifest v1.Manifest
	if err = json.Unmarshal(bytes, &manifest); err != nil {
		return nil, err
	}

	var d digest.Digest
	{
		// shadow manifest so that we can safely
		// strip annotations before calculating
		// the digest
		manifest := manifest
		manifest.Annotations = map[string]string{}
		bytes, err := json.Marshal(&manifest)
		if err != nil {
			return nil, err
		}

		d = digest.FromBytes(bytes)
		if d == options.IfNoMatch {
			return &FetchResponse{Matched: true, Digest: d}, nil
		}
	}

	files, err := s.fetchFiles(ctx, store, manifest)
	if err != nil {
		return nil, err
	}

	return &FetchResponse{Files: files, Digest: d}, nil
}

// fetchFiles retrieves the associated flipt feature content files from the content fetcher.
// It traverses the provided manifests and returns a slice of file instances with appropriate
// content type extensions.
func (s *Store) fetchFiles(ctx context.Context, store oras.ReadOnlyTarget, manifest v1.Manifest) ([]fs.File, error) {
	var files []fs.File

	created, err := time.Parse(time.RFC3339, manifest.Annotations[v1.AnnotationCreated])
	if err != nil {
		return nil, err
	}

	for _, layer := range manifest.Layers {
		mediaType, encoding, err := getMediaTypeAndEncoding(layer)
		if err != nil {
			return nil, fmt.Errorf("layer %q: %w", layer.Digest, err)
		}

		if mediaType != MediaTypeFliptNamespace {
			return nil, fmt.Errorf("layer %q: type %q: %w", layer.Digest, mediaType, ErrUnexpectedMediaType)

package config

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"time"

	"github.com/mitchellh/mapstructure"
	"github.com/spf13/viper"
	"golang.org/x/exp/constraints"
)

const Version = "1.0"
const EnvPrefix = "FLIPT"

var DecodeHooks = []mapstructure.DecodeHookFunc{
	mapstructure.StringToTimeDurationHookFunc(),
	stringToSliceHookFunc(),
	stringToEnumHookFunc(stringToLogEncoding),
	stringToEnumHookFunc(stringToCacheBackend),
	stringToEnumHookFunc(stringToTracingExporter),
	stringToEnumHookFunc(stringToScheme),
	stringToEnumHookFunc(stringToDatabaseProtocol),
	stringToEnumHookFunc(stringToAuthMethod),
}

// Config contains all of Flipts configuration needs.
//
// The root of this structure contains a collection of sub-configuration categories.
//
// Each sub-configuration (e.g. LogConfig) optionally implements either or both of
// the defaulter or validator interfaces.
// Given the sub-config implements a `setDefaults(*viper.Viper) []string` method
// then this will be called with the viper context before unmarshalling.
// This allows the sub-configuration to set any appropriate defaults.
// Given the sub-config implements a `validate() error` method
// then this will be called after unmarshalling, such that the function can emit
// any errors derived from the resulting state of the configuration.
type Config struct {
	Version        string               `json:"version,omitempty" mapstructure:"version,omitempty" yaml:"version,omitempty"`
	Audit          AuditConfig          `json:"audit,omitempty" mapstructure:"audit" yaml:"audit,omitempty"`
	Authentication AuthenticationConfig `json:"authentication,omitempty" mapstructure:"authentication" yaml:"authentication,omitempty"`
	Cache          CacheConfig          `json:"cache,omitempty" mapstructure:"cache" yaml:"cache,omitempty"`
	Cors           CorsConfig           `json:"cors,omitempty" mapstructure:"cors" yaml:"cors,omitempty"`
	Database       DatabaseConfig       `json:"db,omitempty" mapstructure:"db" yaml:"db,omitempty"`
	Diagnostics    DiagnosticConfig     `json:"diagnostics,omitempty" mapstructure:"diagnostics" yaml:"diagnostics,omitempty"`
	Experimental   ExperimentalConfig   `json:"experimental,omitempty" mapstructure:"experimental" yaml:"experimental,omitempty"`
	Log            LogConfig            `json:"log,omitempty" mapstructure:"log" yaml:"log,omitempty"`
	Meta           MetaConfig           `json:"meta,omitempty" mapstructure:"meta" yaml:"meta,omitempty"`
	Analytics      AnalyticsConfig      `json:"analytics,omitempty" mapstructure:"analytics" yaml:"analytics,omitempty"`
	Server         ServerConfig         `json:"server,omitempty" mapstructure:"server" yaml:"server,omitempty"`
	Storage        StorageConfig        `json:"storage,omitempty" mapstructure:"storage" yaml:"storage,omitempty"`
	Tracing        TracingConfig        `json:"tracing,omitempty" mapstructure:"tracing" yaml:"tracing,omitempty"`
	UI             UIConfig             `json:"ui,omitempty" mapstructure:"ui" yaml:"ui,omitempty"`
}

type Result struct {
	Config   *Config
	Warnings []string
}

// Dir returns the default root directory for Flipt configuration
func Dir() (string, error) {
	configDir, err := os.UserConfigDir()
	if err != nil {
		return "", fmt.Errorf("getting user config dir: %w", err)
	}

	return filepath.Join(configDir, "flipt"), nil
}

func Load(path string) (*Result, error) {
	v := viper.New()
	v.SetEnvPrefix(EnvPrefix)
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.AutomaticEnv()

	var cfg *Config

	if path == "" {
		cfg = Default()
	} else {
		cfg = &Config{}
		v.SetConfigFile(path)
		if err := v.ReadInConfig(); err != nil {
			return nil, fmt.Errorf("loading configuration: %w", err)
		}
	}

	var (
		result      = &Result{Config: cfg}
		deprecators []deprecator
		defaulters  []defaulter
		validators  []validator
	)

	f := func(field any) {
		// for-each deprecator implementing field we collect
		// them up and return them to be run before unmarshalling and before setting defaults.
		if deprecator, ok := field.(deprecator); ok {
			deprecators = append(deprecators, deprecator)
		}

		// for-each defaulter implementing fields we invoke
		// setting any defaults during this prepare stage
		// on the supplied viper.
		if defaulter, ok := field.(defaulter); ok {
			defaulters = append(defaulters, defaulter)
		}

		// for-each validator implementing field we collect
		// them up and return them to be validated after
		// unmarshalling.
		if validator, ok := field.(validator); ok {
			validators = append(validators, validator)
		}
	}

	// invoke the field visitor on the root config firsts
	root := reflect.ValueOf(cfg).Interface()
	f(root)

	// these are reflected config top-level types for fields where
	// they have been marked as experimental and their associated
	// flag has enabled set to false.
	var skippedTypes []reflect.Type

	val := reflect.ValueOf(cfg).Elem()
	for i := 0; i < val.NumField(); i++ {
		// search for all expected env vars since Viper cannot
		// infer when doing Unmarshal + AutomaticEnv.
		// see: https://github.com/spf13/viper/issues/761
		structField := val.Type().Field(i)
		if exp := structField.Tag.Get("experiment"); exp != "" {
			// TODO(georgemac): register target for skipping
			if !v.GetBool(fmt.Sprintf("experimental.%s.enabled", exp)) {
				skippedTypes = append(skippedTypes, structField.Type)
			}
		}

		key := fieldKey(structField)
		bindEnvVars(v, getFliptEnvs(), []string{key}, structField.Type)

		field := val.Field(i).Addr().Interface()
		f(field)
	}

	// run any deprecations checks
	for _, deprecator := range deprecators {
		warnings := deprecator.deprecations(v)
		for _, warning := range warnings {
			result.Warnings = append(result.Warnings, warning.Message())
		}
	}

	// run any defaulters
	for _, defaulter := range defaulters {
		if err := defaulter.setDefaults(v); err != nil {
			return nil, err
		}
	}

	if err := v.Unmarshal(cfg, viper.DecodeHook(
		mapstructure.ComposeDecodeHookFunc(
			append(DecodeHooks, experimentalFieldSkipHookFunc(skippedTypes...))...,
		),
	)); err != nil {
		return nil, err
	}

	// run any validation steps
	for _, validator := range validators {
		if err := validator.validate(); err != nil {
			return nil, err
		}
	}

	return result, nil
}

type defaulter interface {
	setDefaults(v *viper.Viper) error
}

type validator interface {
	validate() error
}

type deprecator interface {
	deprecations(v *viper.Viper) []deprecated
}

// fieldKey returns the name to be used when deriving a fields env var key.
// If marked as squash the key will be the empty string.
// Otherwise, it is derived from the lowercase name of the field.
func fieldKey(field reflect.StructField) string {
	if tag := field.Tag.Get("mapstructure"); tag != "" {
		tag, attr, ok := strings.Cut(tag, ",")
		if !ok || attr == "squash" || attr == "omitempty" {
			return tag
		}
	}

	return strings.ToLower(field.Name)
}

type envBinder interface {
	MustBindEnv(...string)
}

// bindEnvVars descends into the provided struct field binding any expected
// environment variable keys it finds reflecting struct and field tags.
func bindEnvVars(v envBinder, env, prefixes []string, typ reflect.Type) {
	// descend through pointers
	if typ.Kind() == reflect.Pointer {
		typ = typ.Elem()
	}

	switch typ.Kind() {
	case reflect.Map:
		// recurse into bindEnvVars while signifying that the last
		// key was unbound using the wildcard "*".
		bindEnvVars(v, env, append(prefixes, wildcard), typ.Elem())

		return
	case reflect.Struct:
		for i := 0; i < typ.NumField(); i++ {
			var (
				structField = typ.Field(i)
				key         = fieldKey(structField)
			)

			bind(env, prefixes, key, func(prefixes []string) {
				bindEnvVars(v, env, prefixes, structField.Type)
			})
		}

		return
	}

	bind(env, prefixes, "", func(prefixes []string) {
		v.MustBindEnv(strings.Join(prefixes, "."))
	})
}

const wildcard = "*"

func appendIfNotEmpty(s []string, v ...string) []string {
	for _, vs := range v {
		if vs != "" {
			s = append(s, vs)
		}
	}

	return s

